const body = $input.first().json.body || $input.first().json;
const transaction = body.obj || body;

// Extract booking reference
const merchantOrderId = transaction?.order?.merchant_order_id || '';
const isBooking = merchantOrderId.startsWith('BOOKING-');
const bookingId = isBooking ? merchantOrderId.replace('BOOKING-', '').trim() : '';
const success = transaction?.success === true || transaction?.success === 'true';
const txnId = transaction?.id ? String(transaction.id) : '';

return [{
  json: {
    success,
    isBooking,
    bookingId,
    txnId,
    merchantOrderId,
    hmac: body.hmac || ''
  }
}];
